"""Core service surface for NpcMind.

Provides process health reporting plus a stateless behavior-tree evaluator.
Each ``evaluate_behavior`` call executes exactly one tick of the supplied
tree against the supplied blackboard; no state is kept between calls.
"""

from __future__ import annotations

from typing import Any

from . import __version__

STATUSES = ("SUCCESS", "FAILURE", "RUNNING")
_COMPOSITE_TYPES = ("sequence", "selector")
_CONDITION_OPS = ("exists", "equals", "not_equals")
_ACTION_OPS = ("set", "delete", "status")


class TreeError(ValueError):
    """Raised when a behavior-tree request fails structural validation."""


def _is_valid_key(key: Any) -> bool:
    return isinstance(key, str) and key != ""


def _json_equal(a: Any, b: Any) -> bool:
    """JSON type-sensitive equality: booleans never equal numbers."""
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(_json_equal(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(_json_equal(x, y) for x, y in zip(a, b))
    return a == b


def _validate_node(node: Any, path: str, seen_ids: set[str]) -> None:
    if not isinstance(node, dict):
        raise TreeError(f"node at {path} must be an object")
    node_id = node.get("id")
    if not isinstance(node_id, str) or node_id == "":
        raise TreeError(f"node at {path} requires a non-empty string id")
    if node_id in seen_ids:
        raise TreeError(f"duplicate node id {node_id!r} at {path}")
    seen_ids.add(node_id)
    where = f"node {node_id!r}"

    node_type = node.get("type")
    if node_type in _COMPOSITE_TYPES:
        children = node.get("children", [])
        if not isinstance(children, list):
            raise TreeError(f"{where}: children must be a list")
        for index, child in enumerate(children):
            _validate_node(child, f"{path}.children[{index}]", seen_ids)
    elif node_type == "condition":
        op = node.get("op")
        if op not in _CONDITION_OPS:
            raise TreeError(f"{where}: unknown condition op {op!r}")
        if not _is_valid_key(node.get("key")):
            raise TreeError(f"{where}: condition requires a non-empty string key")
        if op in ("equals", "not_equals") and "value" not in node:
            raise TreeError(f"{where}: condition op {op!r} requires a value")
    elif node_type == "action":
        op = node.get("op")
        if op not in _ACTION_OPS:
            raise TreeError(f"{where}: unknown action op {op!r}")
        if op in ("set", "delete") and not _is_valid_key(node.get("key")):
            raise TreeError(f"{where}: action op {op!r} requires a non-empty string key")
        if op == "set" and "value" not in node:
            raise TreeError(f"{where}: action op 'set' requires a value")
        if op == "status" and node.get("status") not in STATUSES:
            raise TreeError(f"{where}: illegal status {node.get('status')!r}")
    else:
        raise TreeError(f"{where}: unknown node type {node_type!r}")


def _run_condition(node: dict, blackboard: dict) -> str:
    op = node["op"]
    key = node["key"]
    if op == "exists":
        ok = key in blackboard
    elif key not in blackboard:
        ok = False
    elif op == "equals":
        ok = _json_equal(blackboard[key], node["value"])
    else:  # not_equals
        ok = not _json_equal(blackboard[key], node["value"])
    return "SUCCESS" if ok else "FAILURE"


def _run_action(node: dict, blackboard: dict) -> str:
    op = node["op"]
    if op == "set":
        blackboard[node["key"]] = node["value"]
        return "SUCCESS"
    if op == "delete":
        blackboard.pop(node["key"], None)
        return "SUCCESS"
    return node["status"]  # op == "status"


def _tick(node: dict, blackboard: dict, trace: list) -> str:
    node_type = node["type"]
    if node_type == "sequence":
        status = "SUCCESS"
        for child in node.get("children", []):
            status = _tick(child, blackboard, trace)
            if status != "SUCCESS":
                break
    elif node_type == "selector":
        status = "FAILURE"
        for child in node.get("children", []):
            status = _tick(child, blackboard, trace)
            if status != "FAILURE":
                break
    elif node_type == "condition":
        status = _run_condition(node, blackboard)
    else:  # action
        status = _run_action(node, blackboard)
    trace.append({"id": node["id"], "type": node_type, "status": status})
    return status


class Service:
    """Health reporting plus stateless behavior-tree evaluation."""

    name = "npcmind"
    version = __version__

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    def evaluate_behavior(self, request: dict) -> dict:
        """Execute one tick of ``request['tree']`` against the blackboard.

        Raises ValueError (TreeError) when the request structure, the tree,
        or the blackboard is invalid; no partial result is produced.
        """
        if not isinstance(request, dict):
            raise TreeError("request must be a JSON object")
        if "tree" not in request:
            raise TreeError("request is missing 'tree'")
        tree = request["tree"]
        blackboard = request.get("blackboard", {})
        if not isinstance(blackboard, dict):
            raise TreeError("blackboard must be an object")
        for key in blackboard:
            if not _is_valid_key(key):
                raise TreeError(f"blackboard key {key!r} must be a non-empty string")

        _validate_node(tree, "root", set())

        board = dict(blackboard)
        trace: list = []
        status = _tick(tree, board, trace)
        return {"status": status, "blackboard": board, "trace": trace}

"""HTTP entry point for NpcMind."""

from __future__ import annotations

import argparse
import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from .service import Service


def _reject_constant(value: str) -> None:
    raise ValueError(f"invalid JSON constant {value!r}")


def env_address() -> tuple[str, int]:
    raw = os.environ.get("NPCMIND_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid NPCMIND_ADDR: {raw!r}")
    return host, int(port)


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: dict) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def do_POST(self) -> None:
        if self.path != "/v1/behavior-trees/evaluate":
            self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})
            return
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            length = 0
        raw = self.rfile.read(max(length, 0))
        try:
            request = json.loads(raw.decode("utf-8"), parse_constant=_reject_constant)
        except ValueError as exc:
            self.send_json(400, {"error": {"code": "invalid_json", "message": f"request body is not valid JSON: {exc}"}})
            return
        try:
            result = self.service.evaluate_behavior(request)
        except ValueError as exc:
            self.send_json(422, {"error": {"code": "invalid_tree", "message": str(exc)}})
            return
        self.send_json(200, result)

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def main() -> int:
    parser = argparse.ArgumentParser(prog="npcmind.server", description="游戏 AI 与 NPC 智能行为引擎")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"NpcMind listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import json
import unittest

from npcmind.service import Service


def condition(node_id, op, key, value=None):
    node = {"id": node_id, "type": "condition", "op": op, "key": key}
    if op in ("equals", "not_equals"):
        node["value"] = value
    return node


def action(node_id, op, key=None, value=None, status=None):
    node = {"id": node_id, "type": "action", "op": op}
    if key is not None:
        node["key"] = key
    if op == "set":
        node["value"] = value
    if op == "status":
        node["status"] = status
    return node


class EvaluateBehaviorTest(unittest.TestCase):
    def setUp(self):
        self.service = Service()

    def evaluate(self, tree, blackboard=None):
        request = {"tree": tree}
        if blackboard is not None:
            request["blackboard"] = blackboard
        return self.service.evaluate_behavior(request)

    def test_sequence_all_success(self):
        tree = {
            "id": "root",
            "type": "sequence",
            "children": [
                action("a1", "set", key="x", value=1),
                action("a2", "set", key="y", value=[True, None]),
            ],
        }
        result = self.evaluate(tree)
        self.assertEqual(result["status"], "SUCCESS")
        self.assertEqual(result["blackboard"], {"x": 1, "y": [True, None]})
        self.assertEqual(
            result["trace"],
            [
                {"id": "a1", "type": "action", "status": "SUCCESS"},
                {"id": "a2", "type": "action", "status": "SUCCESS"},
                {"id": "root", "type": "sequence", "status": "SUCCESS"},
            ],
        )

    def test_sequence_short_circuits_on_failure(self):
        tree = {
            "id": "root",
            "type": "sequence",
            "children": [
                action("a1", "status", status="FAILURE"),
                action("a2", "set", key="x", value=1),
            ],
        }
        result = self.evaluate(tree)
        self.assertEqual(result["status"], "FAILURE")
        self.assertEqual(result["blackboard"], {})
        self.assertEqual([t["id"] for t in result["trace"]], ["a1", "root"])

    def test_sequence_stops_on_running(self):
        tree = {
            "id": "root",
            "type": "sequence",
            "children": [
                action("a1", "set", key="x", value=1),
                action("a2", "status", status="RUNNING"),
                action("a3", "set", key="y", value=2),
            ],
        }
        result = self.evaluate(tree)
        self.assertEqual(result["status"], "RUNNING")
        self.assertEqual(result["blackboard"], {"x": 1})
        self.assertEqual([t["id"] for t in result["trace"]], ["a1", "a2", "root"])

    def test_selector_short_circuits_on_success(self):
        tree = {
            "id": "root",
            "type": "selector",
            "children": [
                condition("c1", "exists", "missing"),
                action("a1", "set", key="x", value=1),
                action("a2", "set", key="y", value=2),
            ],
        }
        result = self.evaluate(tree)
        self.assertEqual(result["status"], "SUCCESS")
        self.assertEqual(result["blackboard"], {"x": 1})
        self.assertEqual([t["id"] for t in result["trace"]], ["c1", "a1", "root"])

    def test_selector_all_failure(self):
        tree = {
            "id": "root",
            "type": "selector",
            "children": [
                condition("c1", "exists", "nope"),
                action("a1", "status", status="FAILURE"),
            ],
        }
        result = self.evaluate(tree)
        self.assertEqual(result["status"], "FAILURE")
        self.assertEqual([t["id"] for t in result["trace"]], ["c1", "a1", "root"])

    def test_empty_composites(self):
        result = self.evaluate({"id": "root", "type": "sequence"})
        self.assertEqual(result["status"], "SUCCESS")
        self.assertEqual(result["trace"], [{"id": "root", "type": "sequence", "status": "SUCCESS"}])
        result = self.evaluate({"id": "root", "type": "selector", "children": []})
        self.assertEqual(result["status"], "FAILURE")

    def test_conditions(self):
        self.assertEqual(self.evaluate(condition("c", "exists", "k"), {"k": None})["status"], "SUCCESS")
        self.assertEqual(self.evaluate(condition("c", "exists", "k"))["status"], "FAILURE")
        self.assertEqual(self.evaluate(condition("c", "equals", "k", 1), {"k": 1})["status"], "SUCCESS")
        # JSON type-sensitive: true != 1
        self.assertEqual(self.evaluate(condition("c", "equals", "k", 1), {"k": True})["status"], "FAILURE")
        self.assertEqual(self.evaluate(condition("c", "equals", "k", 1.0), {"k": 1})["status"], "SUCCESS")
        self.assertEqual(self.evaluate(condition("c", "not_equals", "k", 1), {"k": 2})["status"], "SUCCESS")
        # missing key fails even for not_equals
        self.assertEqual(self.evaluate(condition("c", "not_equals", "k", 1))["status"], "FAILURE")

    def test_condition_does_not_modify_blackboard(self):
        result = self.evaluate(condition("c", "equals", "k", 1), {"k": 1})
        self.assertEqual(result["blackboard"], {"k": 1})

    def test_action_delete_missing_key_succeeds(self):
        result = self.evaluate(action("a", "delete", key="ghost"))
        self.assertEqual(result["status"], "SUCCESS")
        self.assertEqual(result["blackboard"], {})

    def test_action_delete_removes_key(self):
        result = self.evaluate(action("a", "delete", key="k"), {"k": 1, "keep": 2})
        self.assertEqual(result["blackboard"], {"keep": 2})

    def test_action_status_running(self):
        result = self.evaluate(action("a", "status", status="RUNNING"))
        self.assertEqual(result["status"], "RUNNING")

    def test_default_blackboard_is_empty_object(self):
        result = self.evaluate(condition("c", "exists", "k"))
        self.assertEqual(result["blackboard"], {})

    def test_input_blackboard_not_mutated(self):
        board = {"k": 1}
        tree = {
            "id": "root",
            "type": "sequence",
            "children": [action("a", "set", key="k", value=2)],
        }
        self.evaluate(tree, board)
        self.assertEqual(board, {"k": 1})

    def test_nested_trace_order(self):
        tree = {
            "id": "root",
            "type": "selector",
            "children": [
                {
                    "id": "seq",
                    "type": "sequence",
                    "children": [
                        condition("c1", "exists", "nope"),
                        action("a1", "set", key="x", value=1),
                    ],
                },
                action("a2", "set", key="y", value=2),
            ],
        }
        result = self.evaluate(tree)
        self.assertEqual(result["status"], "SUCCESS")
        self.assertEqual(result["blackboard"], {"y": 2})
        self.assertEqual([t["id"] for t in result["trace"]], ["c1", "seq", "a2", "root"])


class EvaluateBehaviorErrorsTest(unittest.TestCase):
    def setUp(self):
        self.service = Service()

    def assert_invalid(self, request, *fragments):
        with self.assertRaises(ValueError) as ctx:
            self.service.evaluate_behavior(request)
        for fragment in fragments:
            self.assertIn(fragment, str(ctx.exception))

    def test_missing_tree(self):
        self.assert_invalid({}, "tree")

    def test_request_not_object(self):
        self.assert_invalid([1, 2], "object")

    def test_blackboard_not_object(self):
        self.assert_invalid({"tree": {"id": "r", "type": "sequence"}, "blackboard": []}, "blackboard")

    def test_blackboard_invalid_key(self):
        self.assert_invalid(
            {"tree": {"id": "r", "type": "sequence"}, "blackboard": {"": 1}}, "blackboard"
        )

    def test_tree_not_object(self):
        self.assert_invalid({"tree": 42}, "root")

    def test_missing_id_reports_path(self):
        tree = {"id": "root", "type": "sequence", "children": [{"type": "action", "op": "delete", "key": "k"}]}
        self.assert_invalid({"tree": tree}, "root.children[0]")

    def test_empty_id(self):
        self.assert_invalid({"tree": {"id": "", "type": "sequence"}}, "id")

    def test_duplicate_id(self):
        tree = {
            "id": "root",
            "type": "sequence",
            "children": [
                action("dup", "delete", key="k"),
                action("dup", "delete", key="k"),
            ],
        }
        self.assert_invalid({"tree": tree}, "dup")

    def test_unknown_node_type(self):
        self.assert_invalid({"tree": {"id": "n1", "type": "parallel"}}, "n1")

    def test_unknown_condition_op(self):
        self.assert_invalid({"tree": condition("c", "gt", "k", 1)}, "c")

    def test_condition_missing_value(self):
        self.assert_invalid({"tree": {"id": "c", "type": "condition", "op": "equals", "key": "k"}}, "value")

    def test_condition_missing_key(self):
        self.assert_invalid({"tree": {"id": "c", "type": "condition", "op": "exists"}}, "key")

    def test_unknown_action_op(self):
        self.assert_invalid({"tree": {"id": "a", "type": "action", "op": "print"}}, "a")

    def test_action_set_missing_value(self):
        self.assert_invalid({"tree": {"id": "a", "type": "action", "op": "set", "key": "k"}}, "value")

    def test_action_status_illegal(self):
        self.assert_invalid({"tree": action("a", "status", status="BROKEN")}, "BROKEN")

    def test_children_not_list(self):
        self.assert_invalid({"tree": {"id": "r", "type": "sequence", "children": {}}}, "children")


if __name__ == "__main__":
    unittest.main()

